&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;25 vakantiedagen&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We gaan direct sparen voor je pensioen&lt;/span&gt;&lt;/p&gt;
